const teams=['BSP','Vibers','BackBenchers','Captain Code','Ocean Four','BHoods'];
const totals=Object.fromEntries(teams.map(t=>[t,0]));
const form=document.querySelector('#donation-form'),teamSelect=document.querySelector('#team'),amount=document.querySelector('#amount'),dialog=document.querySelector('#thanks');
let total=0,gifts=0;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
teams.forEach((team,i)=>{const option=new Option(team,team);teamSelect.add(option);const card=document.createElement('button');card.type='button';card.className='team-card';card.innerHTML='<span class="team-symbol">'+['BS','VB','BB','&lt;/&gt;','O4','BH'][i]+'</span><span><strong>'+team+'</strong><small id="team-total-'+i+'">Be their first demo donor</small></span><span class="arrow">↗</span>';card.setAttribute('aria-label','Donate with '+team);card.addEventListener('click',()=>{teamSelect.value=team;document.querySelector('#donate').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});teamSelect.focus({preventScroll:true})});document.querySelector('#team-grid').append(card)});
function updateAmount(){document.querySelectorAll('[data-amount]').forEach(b=>{const selected=Number(b.dataset.amount)===Number(amount.value);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});document.querySelector('.pay').textContent='Donate '+(amount.value&&amount.validity.valid?money(Number(amount.value)):'your amount')+' · Demo ♥'}
document.querySelectorAll('[data-amount]').forEach(b=>b.addEventListener('click',()=>{amount.value=b.dataset.amount;updateAmount()}));amount.addEventListener('input',updateAmount);updateAmount();
form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const value=Number(amount.value),team=teamSelect.value;if(!teams.includes(team)||!Number.isFinite(value)||value<1||value>100000)return;total=Math.round((total+value)*100)/100;totals[team]=Math.round((totals[team]+value)*100)/100;gifts++;document.querySelector('#total').textContent=money(total);document.querySelector('#progress').style.width=Math.min(total/10000*100,100)+'%';document.querySelector('#percent').textContent=(total/10000*100).toFixed(1)+'% of the way there';document.querySelector('#gifts').textContent=gifts+' demo gift'+(gifts===1?'':'s');document.querySelector('#team-total-'+teams.indexOf(team)).textContent=money(totals[team])+' in demo gifts';const name=document.querySelector('#donor-name').value.trim();document.querySelector('#thanks-message').textContent='Congratulations'+(name?', '+name:'')+'! Your '+money(value)+' demo donation for '+team+' is complete. Thank you for cheering on SCHOOL FOR CODING AGENTS and helping little dreams grow big.';dialog.showModal()});
document.querySelectorAll('.close,.close-thanks').forEach(b=>b.addEventListener('click',()=>dialog.close()));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'prepare_demo_donation',description:'Select a team and amount in the demo donation form. Does not complete payment.',inputSchema:{type:'object',properties:{team:{type:'string',enum:teams},amount:{type:'number',minimum:1,maximum:100000}},required:['team','amount'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!teams.includes(input.team)||typeof input.amount!=='number'||!Number.isFinite(input.amount)||input.amount<1||input.amount>100000||Math.abs(input.amount*100-Math.round(input.amount*100))>0.000001)throw new Error('Choose a listed team and an amount from 1 to 100000 with at most two decimal places.');teamSelect.value=input.team;amount.value=String(input.amount);updateAmount();document.querySelector('#donate').scrollIntoView();return {team:teamSelect.value,amount:Number(amount.value),status:'prepared',charged:false}}})).catch(()=>{})}catch{}}
